def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); out=[row[:] for row in grid]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==0 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(y+dy,x+dx)
            if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]!=0 and q not in seen:
              seen.add(q); stack.append(q)
        r0=min(y for y,x in comp); r1=max(y for y,x in comp)
        c0=min(x for y,x in comp); c1=max(x for y,x in comp)
        levels={}
        for y,x in comp:
          d=min(y-r0,r1-y,x-c0,c1-x)
          levels.setdefault(d,set()).add(grid[y][x])
        # Read the nested bands from the outside toward the center.
        order=[]
        for d in sorted(levels):
          for color in sorted(levels[d]):
            if color not in order: order.append(color)
        if len(order)>1:
          mapping=dict(zip(order,reversed(order)))
          for y,x in comp: out[y][x]=mapping.get(grid[y][x],grid[y][x])
    return out
